\begin{document}

\section*{টিস্যু ও টিস্যুতন্ত্র}
\textbf{Tissue and Tissue System}

\begin{itemize}
    \item টিস্যু
    \item ভাজক টিস্যু
    \item প্রোটোডাম
    \item প্রোকায়মিয়াম
    \item গ্রাউন্ড মেরিস্টেম
    \item পত্ররন্শ্র
    \item হাইডাথোড
    \item ভাস্কুলার বান্ডল
    \item জাইলেম
    \item ফ্রোয়েম
\end{itemize}

\begin{figure}[h]
    \centering
    \includegraphics[width=0.8\textwidth]{image.png}
    \caption{একটি টিস্যু সম্পর্কে}
\end{figure}

\begin{itemize}
    \item ভাজক টিস্যু সম্পর্কে
    \item এপিডামিল, গ্রাউন্ড ও ভাস্কুলার টিস্যুতন্ত্রের অবস্থান, গঠন ও কাজ
    \item টিস্যুতন্ত্রের চিহ্নিত চিত্র আঁকন
    \item একবীজপত্রী উত্তিদের মূল ও কাঁদের চিহ্নিত চিত্র আঁকন
    \item ব্যবহারিক: একবীজপত্রী উত্তিদের মূল ও কাঁদের প্রস্থচ্ছেদ শনাক্তকরণ
\end{itemize}

\begin{table}[h]
\centering
\begin{tabular}{|c|c|}
\hline
পাঠ 1 & ভাজক টিস্যু \\
\hline
পাঠ 2 & টিস্যুতন্ত্র \\
\hline
পাঠ 3 & ভিত্তি টিস্যুতন্ত্র \\
\hline
পাঠ 4 & ভাস্কুলার টিস্যুতন্ত্র \\
\hline
পাঠ 5 & মূল ও কাঁদের প্রাথমিক অন্তর্গতন \\
\hline
পাঠ 6 & একবীজপত্রী উত্তিদের মূল ও কাঁদের অন্তর্গতন (প্রস্থচ্ছেদ) পর্যবেক্ষণ \\
\hline
পাঠ 7 & এবং শনাক্তকরণ \\
\hline
\end{tabular}
\caption{পাঠ পরিকল্পনা}
\end{table}

\end{document}

