\documentclass{article}
\usepackage{graphicx}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{hyperref}
\usepackage{geometry}
\geometry{a4paper, margin=1in}

\begin{document}

\begin{figure}[h]
    \centering
    \includegraphics[width=0.8\textwidth]{path/to/your/image.png}
    \caption{চিত্র-৮.১: আদর্শ ভাজক টিসু}
    \label{fig:meristematic_tissue}
\end{figure}

\section{ভাজক টিসুর বৈশিষ্ট্য (Characteristics of Meristematic Tissue)}

\begin{enumerate}
    \item ভাজক টিসুর কোষগুলো সজীব, তরুণ (অপরিণত) এবং সর্বদাই বিভাজনরত অবস্থায় থাকে।
    \item কোষ প্রাচীর পাতলা এবং সেলুলোজ দ্বারা গঠিত।
    \item নিউক্লিয়াস সুস্পষ্ট, বড় ও কোষের কেন্দ্রাংশে অবস্থিত।
    \item কোষগুলো ঘনভাবে সন্নিবেশিত থাকে এবং এদের মাঝে আতঃকোষীয় ফাঁকা স্থান থাকে না।
    \item কোষের আকৃতি গোলাকার, ডিয়াকার, আয়তাকার, পঞ্চভুজ বা যড়ভুজাকার।
    \item কোষগুলোর বিপাকীয় হার বেশি এবং সর্বদাই সক্রিয়।
    \item কোষে কোনো প্রকার সংক্ষিপ্ত খাদ্য, বর্জ্য ও ফরিত পদার্থ থাকে না।
    \item প্লাস্টিডগুলো প্রোগ্লাস্টিড অবস্থায় থাকে।
    \item ভাজক টিসুর কোষে ঘন সাইটোপ্লাজম উপস্থিত এবং সেখানে সাধারণত কোনো কোষ গঠন থাকে না।
    \item এ টিসুর কোষগুলো সাধারণত ছোট এবং এরা সমব্যাসী।
    \item ভাজক টিসু উদ্ভিদের বর্ধিষ্ঠ অংশে অবস্থান করে।
    \item প্রাইমারি ভাজক টিসু ভ্রু হতে এবং সেকেন্ডারি ভাজক টিসু স্থায়ী টিসু হতে উৎপত্তি লাভ করে।
\end{enumerate}

\begin{flushright}
\textbf{জেনে রাখো}
\end{flushright}

\begin{flushright}
\textbf{M. F. Xavier Bichat সর্বপ্রথম টিসু (tissue) শব্দটি ব্যবহার করেন। বহুকোষী জীবদেহে শ্রমবিভাজনের কারণে টিসু ও টিসুযুগ্মের সৃষ্টি হয়। প্রধানত বিভাজন ক্ষমতার উপর ভিত্তি করে উদ্ভিদ টিসুকে দু'ভাগে ভাগ করা হয়। যথা-}
\begin{itemize}
    \item ভাজক টিসু ও \item স্থায়ী টিসু।
\end{itemize}
\end{flushright}

\end{document}

\documentclass{article}
\usepackage{fontspec}
\setmainfont{Arial}
\begin{document}

\section{বাজক টিস্যুর কাজ (Functions of Meristematic Tissue)}

\begin{enumerate}
    \item ভাজক টিস্যু থেকে নতুন নতুন টিস্যু সৃষ্টির মাধ্যমে উত্তিদের দৈহিক গঠন ও দৈহিক বৃদ্ধি ঘটে।
    \item ভাজক টিস্যু হতে স্থায়ী টিস্যুর সৃষ্টি হয়।
    \item ক্ষতস্থান পূরণ করা ভাজক টিস্যুর কাজ।
    \item পাশ্চাত্য ভাজক টিস্যুর বিভাজনের ফলে উত্তিদের ব্যাস বৃদ্ধি পায় এবং উত্তিদ ক্রমে মোটা হয়।
\end{enumerate}

\section{বাজক টিস্যুর শ্রেণিবিভাগ (Classification of Meristematic Tissue)}

ভাজক টিস্যুকে নানাভাবে শ্রেণিবিভাগ করা হয়। শ্রেণিবিভাগের ভিত্তিগুলো হলো– (i) উৎপত্তি অনুসারে, (ii) অবস্থান অনুসারে, (iii) কাজ অনুসারে এবং (iv) কোষ বিভাজনের তল অনুসারে।

(i) উৎপত্তি অনুসারে: উৎপত্তি অনুসারে ভাজক টিস্যু তিন প্রকার। যথা–

ক. প্রারম্ভিক ভাজক টিস্যু (Promeristem): মূল বা কাঁধের শীর্ষদেশে একটি ক্ষুদ্র অংশ রয়েছে যেখান থেকে পরবর্তী ভাজক টিস্যুর উৎপত্তি ঘটে, এ অংশটিকে প্রারম্ভিক ভাজক টিস্যু বলে। এ অঞ্চল থেকেই প্রাথমিক ভাজক টিস্যু সৃষ্টি হয়।

খ. প্রাইমারি ভাজক টিস্যু (Primary Meristem): প্রারম্ভিক ভাজক টিস্যু হতে যে ভাজক টিস্যুর উৎপত্তি ঘটে তাকে প্রাইমারি ভাজক টিস্যু বলে। এরা ক্রুঞ্চ কোষ হতে সরাসরি সৃষ্টি হয়ে মৃত্যু পর্যন্ত বিভাজনক্ষম থাকে। প্রাথমিক ভাজক টিস্যু দ্বারা উত্তিদ দেহের প্রাথমিক বৃদ্ধি হয়। মূল, কাঁধ ও এদের শাখা-প্রশাখার অগ্রভাগে প্রাইমারি ভাজক টিস্যু থাকে।

গ. সেকেন্ডারি ভাজক টিস্যু (Secondary Meristem): স্থায়ী টিস্যু বিভাজনক্ষমতা প্রাপ্ত হয়ে যে নতুন ভাজক টিস্যুর সৃষ্টি করে তাকে সেকেন্ডারি ভাজক টিস্যু বলে। এমন ভাজক টিস্যু উত্তিদেহে প্রথমে থাকে না বরং অনেক পরে সৃষ্টি হয়। যেমন- কর্ক ক্যাথিয়াম, ইন্টারফ্যাসিকুলার ক্যাথিয়াম প্রভৃতি। এদের প্রভাবে মূল বা কাঁধের গোল বৃদ্ধি (পার্শ্বে) ঘটে অর্থাৎ মূল ও কাঁধের পরিধি বৃদ্ধি পায়।

\end{document}

